Use a **discriminated union** so each status carries only its required data. Accept `unknown` at the update boundary and validate it before returning a typed state.

```ts
type ExportStatus =
  | { readonly status: "queued" }
  | { readonly status: "processing"; readonly progress: number }
  | { readonly status: "completed"; readonly downloadUrl: string }
  | { readonly status: "failed"; readonly error: string };

function requireText(value: unknown, field: string): string {
  if (typeof value !== "string" || value.trim() === "") {
    throw new Error(`${field} must be a non-empty string`);
  }
  return value;
}

// Returns a validated replacement state; throws for invalid updates.
function handleStatusUpdate(input: unknown): ExportStatus {
  if (typeof input !== "object" || input === null) {
    throw new Error("Status update must be an object");
  }

  const update = input as Record<string, unknown>;

  switch (update.status) {
    case "queued":
      return { status: "queued" };

    case "processing": {
      const progress = update.progress;

      if (
        typeof progress !== "number" ||
        !Number.isInteger(progress) ||
        progress < 0 ||
        progress > 100
      ) {
        throw new Error("progress must be an integer from 0 to 100");
      }

      return { status: "processing", progress };
    }

    case "completed": {
      const downloadUrl = requireText(update.downloadUrl, "downloadUrl");

      let url: URL;
      try {
        url = new URL(downloadUrl);
      } catch {
        throw new Error("downloadUrl must be an absolute HTTP(S) URL");
      }

      if (url.protocol !== "https:" && url.protocol !== "http:") {
        throw new Error("downloadUrl must use HTTP or HTTPS");
      }

      return { status: "completed", downloadUrl };
    }

    case "failed":
      return {
        status: "failed",
        error: requireText(update.error, "error"),
      };

    default:
      throw new Error("Unknown export status");
  }
}
```

