Configuration comes only from environment variables. Errors identify invalid settings without exposing their values.

`config.ts`

```ts
export interface Config {
  readonly port: number;
  readonly databaseUrl: string;
  readonly databaseToken: string;
  readonly apiBaseUrl: string;
  readonly apiToken: string;
}

type Env = Readonly<Record<string, string | undefined>>;

export function loadConfig(env: Env = process.env): Config {
  function required(name: string): string {
    const value = env[name];
    if (!value || value.trim() === "") {
      throw new Error(`${name} is required`);
    }
    if (value !== value.trim() || /[\r\n\0]/.test(value)) {
      throw new Error(`${name} contains invalid whitespace or control characters`);
    }
    return value;
  }

  function endpoint(name: string, protocols: string[]): string {
    const value = required(name);
    let url: URL;
    try {
      url = new URL(value);
    } catch {
      // Do not propagate parser errors: they may contain credentials.
      throw new Error(`${name} must be a valid absolute URL`);
    }

    if (!protocols.includes(url.protocol) || !url.hostname) {
      throw new Error(`${name} uses an unsupported protocol or has no host`);
    }
    if (url.username || url.password || url.search || url.hash) {
      throw new Error(
        `${name} must not contain credentials, query parameters, or fragments`,
      );
    }
    return value;
  }

  const rawPort = env.PORT ?? "3000";
  if (!/^[0-9]+$/.test(rawPort)) {
    throw new Error("PORT must be an integer between 1 and 65535");
  }
  const port = Number(rawPort);
  if (!Number.isSafeInteger(port) || port < 1 || port > 65535) {
    throw new Error("PORT must be an integer between 1 and 65535");
  }

  return Object.freeze({
    port,
    databaseUrl: endpoint("DATABASE_URL", ["postgres:", "postgresql:"]),
    databaseToken: required("DATABASE_TOKEN"),
    apiBaseUrl: endpoint("API_BASE_URL", ["https:"]),
    apiToken: required("API_TOKEN"),
  });
}
```

`request-logging.ts`

Logs contain a generated request ID, method, status, duration, and completion state. Raw paths are excluded because tokens and personal data can appear in path segments as well as query strings.

```ts
import { randomUUID } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";

export interface RequestLog {
  timestamp: string;
  event: "http_request";
  requestId: string;
  method: string;
  outcome: "completed" | "aborted";
  statusCode: number | null;
  durationMs: number;
}

export type LogSink = (record: RequestLog) => void;

const stdoutSink: LogSink = (record) => {
  process.stdout.write(`${JSON.stringify(record)}\n`);
};

export function createRequestLogger(write: LogSink = stdoutSink) {
  return (
    req: IncomingMessage,
    res: ServerResponse,
    next: () => void,
  ): void => {
    const start = process.hrtime.bigint();
    const requestId = randomUUID();
    let recorded = false;

    // Generate locally rather than trusting a client-supplied identifier.
    res.setHeader("X-Request-ID", requestId);

    function record(outcome: RequestLog["outcome"]): void {
      if (recorded) return;
      recorded = true;
      res.off("finish", onFinish);
      res.off("close", onClose);

      const entry: RequestLog = {
        timestamp: new Date().toISOString(),
        event: "http_request",
        requestId,
        method: /^[A-Z]{1,32}$/.test(req.method ?? "")
          ? req.method!
          : "OTHER",
        outcome,
        statusCode: outcome === "completed" ? res.statusCode : null,
        durationMs: Number(process.hrtime.bigint() - start) / 1e6,
      };

      try {
        write(entry);
      } catch {
        // Logging failures must not crash request handling.
        // Never print the thrown error, which may contain sensitive data.
        process.stderr.write('{"event":"request_logging_failed"}\n');
      }
    }

    function onFinish(): void {
      record("completed");
    }

    function onClose(): void {
      record(res.writableFinished ? "completed" : "aborted");
    }

    res.once("finish", onFinish);
    res.once("close", onClose);
    next();
  };
}
```

