Use a **pure calculation function**: pass in the subtotal, discount rules, validated coupon, and tax rate; return an itemized breakdown. Keep database access, coupon eligibility, and tax-rate lookup outside it.

This example makes the business rules explicit:

- Highest qualifying tier wins, based on the original subtotal.
- Apply tier discount, then one coupon, then tax.
- Clamp discounts so the taxable amount cannot become negative.
- Round each percentage calculation half-up to the nearest minor currency unit.

These are example policies; set the order and rounding to your actual requirements.

```ts
// order-total.ts — TypeScript targeting ES2020+
// Money uses bigint minor units: 10_00n = $10.00.
// Rates use basis points: 1_000 = 10%.

type Tier = Readonly<{
  minimum: bigint;
  discountBps: number;
}>;

type Coupon =
  | Readonly<{ kind: "fixed"; amount: bigint }>
  | Readonly<{ kind: "percentage"; discountBps: number }>;

type TotalInput = Readonly<{
  subtotal: bigint;
  tiers: readonly Tier[];
  coupon?: Coupon;
  taxBps: number;
}>;

function requireMoney(value: bigint): void {
  if (typeof value !== "bigint" || value < 0n) {
    throw new RangeError("Money must be non-negative bigint minor units");
  }
}

function requireRate(bps: number): void {
  if (!Number.isInteger(bps) || bps < 0 || bps > 10_000) {
    throw new RangeError("Rate must be an integer from 0 to 10,000");
  }
}

function percentage(amount: bigint, bps: number): bigint {
  return (amount * BigInt(bps) + 5_000n) / 10_000n;
}

export function calculateOrderTotal(input: TotalInput) {
  const { subtotal, tiers, coupon, taxBps } = input;

  requireMoney(subtotal);
  requireRate(taxBps);

  let selectedTier: Tier | undefined;
  const thresholds = new Set<bigint>();

  for (const tier of tiers) {
    requireMoney(tier.minimum);
    requireRate(tier.discountBps);

    if (thresholds.has(tier.minimum)) {
      throw new RangeError("Tier thresholds must be unique");
    }
    thresholds.add(tier.minimum);

    if (
      subtotal >= tier.minimum &&
      (!selectedTier || tier.minimum > selectedTier.minimum)
    ) {
      selectedTier = tier;
    }
  }

  const tierDiscount = percentage(
    subtotal,
    selectedTier?.discountBps ?? 0,
  );
  const afterTier = subtotal - tierDiscount;

  let couponDiscount = 0n;

  if (coupon) {
    switch (coupon.kind) {
      case "fixed":
        requireMoney(coupon.amount);
        couponDiscount =
          coupon.amount > afterTier ? afterTier : coupon.amount;
        break;

      case "percentage":
        requireRate(coupon.discountBps);
        couponDiscount = percentage(afterTier, coupon.discountBps);
        break;

      default:
        throw new TypeError("Unknown coupon kind");
    }
  }

  const taxableAmount = afterTier - couponDiscount;
  const tax = percentage(taxableAmount, taxBps);

  return {
    subtotal,
    tierDiscount,
    couponDiscount,
    taxableAmount,
    tax,
    total: taxableAmount + tax,
  } as const;
}
```

