Use a **pure calculation function with an explicit sequence of pricing rules**. Keep database access, coupon eligibility, and tax-rate lookup outside it so tests need no mocks.

For this example, the business rules are:

- All amounts use one currency’s integer minor units, such as cents.
- The highest qualifying tier applies to the original subtotal.
- One coupon applies after the tier discount.
- Discounts cannot reduce the taxable amount below zero.
- Tax applies to the discounted amount.
- Each percentage calculation rounds half up to the nearest minor unit.

These are example policies; confirm the applicable tax basis and rounding rules before production use.

```ts
// order-total.ts
// bigint requires an ES2020+ target.

export type Tier = Readonly<{
  minimumSubtotal: bigint;
  discountBps: number; // Basis points: 1,000 = 10%
}>;

export type Coupon =
  | Readonly<{ kind: "percentage"; discountBps: number }>
  | Readonly<{ kind: "fixed"; amount: bigint }>;

export type PricingInput = Readonly<{
  subtotal: bigint;
  tiers: readonly Tier[];
  coupon?: Coupon;
  taxBps: number;
}>;

export type OrderTotal = Readonly<{
  subtotal: bigint;
  tierDiscount: bigint;
  couponDiscount: bigint;
  taxableAmount: bigint;
  tax: bigint;
  total: bigint;
}>;

function requireMoney(value: bigint, name: string): void {
  if (typeof value !== "bigint" || value < 0n) {
    throw new RangeError(`${name} must be non-negative integer minor units`);
  }
}

function requireRate(value: number, name: string): void {
  if (!Number.isInteger(value) || value < 0 || value > 10_000) {
    throw new RangeError(`${name} must be an integer from 0 to 10,000`);
  }
}

// Exact integer arithmetic; rounds half up for non-negative amounts.
function percentageOf(amount: bigint, bps: number): bigint {
  return (amount * BigInt(bps) + 5_000n) / 10_000n;
}

function selectTierRate(subtotal: bigint, tiers: readonly Tier[]): number {
  let selected: Tier | undefined;
  const thresholds = new Set<bigint>();

  for (const tier of tiers) {
    requireMoney(tier.minimumSubtotal, "Tier minimum subtotal");
    requireRate(tier.discountBps, "Tier discount");

    if (thresholds.has(tier.minimumSubtotal)) {
      throw new RangeError("Tier minimum subtotals must be unique");
    }
    thresholds.add(tier.minimumSubtotal);

    if (
      tier.minimumSubtotal <= subtotal &&
      (!selected || tier.minimumSubtotal > selected.minimumSubtotal)
    ) {
      selected = tier;
    }
  }

  return selected?.discountBps ?? 0;
}

function calculateCouponDiscount(
  amount: bigint,
  coupon: Coupon | undefined,
): bigint {
  if (!coupon) return 0n;

  switch (coupon.kind) {
    case "percentage":
      requireRate(coupon.discountBps, "Coupon discount");
      return percentageOf(amount, coupon.discountBps);

    case "fixed":
      requireMoney(coupon.amount, "Coupon amount");
      return coupon.amount > amount ? amount : coupon.amount;

    default: {
      const unexpected: never = coupon;
      throw new TypeError("Unsupported coupon kind");
    }
  }
}

export function calculateOrderTotal(input: PricingInput): OrderTotal {
  requireMoney(input.subtotal, "Subtotal");
  requireRate(input.taxBps, "Tax rate");

  const tierRate = selectTierRate(input.subtotal, input.tiers);
  const tierDiscount = percentageOf(input.subtotal, tierRate);
  const afterTierDiscount = input.subtotal - tierDiscount;

  const couponDiscount = calculateCouponDiscount(
    afterTierDiscount,
    input.coupon,
  );

  const taxableAmount = afterTierDiscount - couponDiscount;
  const tax = percentageOf(taxableAmount, input.taxBps);

  return {
    subtotal: input.subtotal,
    tierDiscount,
    couponDiscount,
    taxableAmount,
    tax,
    total: taxableAmount + tax,
  };
}
```

The returned breakdown makes receipts and debugging straightforward. The discriminated coupon union prevents contradictory fixed and percentage settings. `bigint` avoids floating-point arithmetic and integer overflow; convert amounts to decimal strings at JSON boundaries.

