    expect(calculateOrderTotal({
      subtotal: 1n,
      tiers: [],
      taxBps: 5_000,
    }).tax).toBe(1n);
  });

  it("rejects invalid rates", () => {
    expect(() => calculateOrderTotal({
      subtotal: 100n,
      tiers: [],
      taxBps: -1,
    })).toThrow(/Tax rate/);
  });

  it("rejects ambiguous tier thresholds", () => {
    expect(() => calculateOrderTotal({
      subtotal: 100n,
      tiers: [
        { minimumSubtotal: 0n, discountBps: 100 },
        { minimumSubtotal: 0n, discountBps: 200 },
      ],
      taxBps: 0,
    })).toThrow(/unique/);
  });
